import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure proper types
    target_state["order_id"] = target_state["order_id"].astype("int64")
    target_state["last_seq"] = target_state["last_seq"].astype("int64")

    cdc_events["seq"] = cdc_events["seq"].astype("int64")
    cdc_events["order_id"] = cdc_events["order_id"].astype("int64")

    # Step 1: Remove duplicate events (same seq)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Step 2: Sort by seq to respect log ordering
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # Step 3: Apply replay guard and filter events
    # Build a dict of order_id -> last_seq for quick lookup
    state_dict = {}
    if len(target_state) > 0:
        for _, row in target_state.iterrows():
            state_dict[row["order_id"]] = row["last_seq"]

    # Filter events: skip those where order exists in target_state and seq <= last_seq
    filtered_events = []
    for _, event in cdc_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]

        # Replay guard: skip if order has a row and seq <= last_seq
        if order_id in state_dict and seq <= state_dict[order_id]:
            continue

        filtered_events.append(event)

    if filtered_events:
        filtered_events = pd.DataFrame(filtered_events)
    else:
        filtered_events = pd.DataFrame()

    # Step 4: Apply events in seq order
    # Maintain current state as a dict of order_id -> {status, amount, last_seq}
    current_state = {}
    for _, row in target_state.iterrows():
        order_id = row["order_id"]
        current_state[order_id] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"]
        }

    # Track which orders had a row and their last operation
    orders_with_rows = set(current_state.keys())
    last_op_by_order = {}  # order_id -> (op, seq)

    for _, event in filtered_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]
        op = event["op"]
        status = event["status"]
        amount = event["amount"]

        if op in ["I", "U"]:
            if order_id in current_state:
                # Update existing row
                current_state[order_id]["status"] = status
                # For 'U' with NULL amount, keep existing amount; otherwise use event amount
                if op == "U" and pd.isna(amount):
                    # Keep existing amount
                    pass
                else:
                    current_state[order_id]["amount"] = amount
                current_state[order_id]["last_seq"] = seq
            else:
                # Create new row
                current_state[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq
                }
                orders_with_rows.add(order_id)

            last_op_by_order[order_id] = (op, seq)

        elif op == "D":
            if order_id in current_state:
                del current_state[order_id]
            last_op_by_order[order_id] = (op, seq)

    # Step 5: Build new_state
    new_state_rows = []
    for order_id, state in current_state.items():
        new_state_rows.append({
            "order_id": order_id,
            "status": state["status"],
            "amount": state["amount"],
            "last_seq": state["last_seq"]
        })

    if new_state_rows:
        new_state = pd.DataFrame(new_state_rows)
        new_state = new_state.sort_values("order_id").reset_index(drop=True)
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    # Ensure dtypes
    new_state["order_id"] = new_state["order_id"].astype("int64")
    new_state["status"] = new_state["status"].astype(object)
    new_state["amount"] = new_state["amount"].astype("float64")
    new_state["last_seq"] = new_state["last_seq"].astype("int64")

    # Step 6: Build tombstones
    # Tombstones: orders that had a row and whose last applied event was 'D'
    tombstone_rows = []
    for order_id in orders_with_rows:
        if order_id in last_op_by_order:
            op, seq = last_op_by_order[order_id]
            if op == "D":
                tombstone_rows.append({
                    "order_id": order_id,
                    "deleted_seq": seq
                })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
        tombstones = tombstones.sort_values("order_id").reset_index(drop=True)
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])

    # Ensure dtypes
    tombstones["order_id"] = tombstones["order_id"].astype("int64")
    tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
